$name='AssetFlowAgent';if(Get-Service $name -ErrorAction SilentlyContinue){Stop-Service $name -Force;sc.exe delete $name|Out-Null};Remove-ItemProperty -Path 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Run' -Name 'AssetFlowAgentTray' -ErrorAction SilentlyContinue;Get-Process 'AssetFlow.Agent' -ErrorAction SilentlyContinue|Stop-Process -Force;Write-Host 'Service and tray app removed. Inventory identity remains in ProgramData\AssetFlow.'
